// FUNCTION: BFME2 0x0032B2A5 size=228 name=?validateAllyEnemyList@SidesList@@QAE_NABVAsciiString@@AAV2@@Z evidence=N:ledger tier=A
Bool SidesList::validateAllyEnemyList(const AsciiString &tname, AsciiString &allies)
{
	Bool modified = false;
	AsciiString str, newstr, token;
	str = allies;
	newstr.clear();
	while (str.nextToken(&token, 0))
	{
		if (token == tname)
		{
			modified = true;
			continue;
		}
		SidesInfo *si = findSideInfo(token);
		if (!si)
		{
			modified = true;
			continue;
		}
		if (!newstr.isEmpty())
			newstr.concat(" ");
		newstr.concat(token);
	}
	allies = newstr;
	return modified;
}

