// FUNCTION: BFME2 0x0032C1F7 size=118 name=?removeFromIndex@TeamsInfoRec@@QAEXH@Z evidence=N:ledger tier=A
void TeamsInfoRec::removeFromIndex(Int index)
{
	TeamsInfo *team = &m_teams[index];
	short overriddenBy = team->m_overriddenByID;
	if (!overriddenBy)
	{
		if (team->m_overridesID)
		{
			team->m_indexIt->second = team->m_overridesID;
			m_teams[team->m_overridesID].m_overriddenByID = 0;
		}
		else
		{
			m_index.erase(team->m_indexIt);
		}
	}
	else
	{
		m_teams[overriddenBy].m_overridesID = team->m_overridesID;
		if (team->m_overridesID)
			m_teams[team->m_overridesID].m_overriddenByID = team->m_overriddenByID;
	}
}

// FUNCTION: BFME2 0x0032C26D size=87 name=?removeTeam@TeamsInfoRec@@QAEXH@Z evidence=N:ledger tier=A
void TeamsInfoRec::removeTeam(Int index)
{
	removeFromIndex(index);
	TeamsInfo *team = &m_teams[index];
	team->m_dict.clear();
	m_teams[team->m_next].m_prev = team->m_prev;
	m_teams[team->m_prev].m_next = team->m_next;
	short oldFreeHead = m_freeHead;
	--m_numActive;
	team->m_next = oldFreeHead;
	m_freeHead = (short)index;
}

// FUNCTION: BFME2 0x0032C2C4 size=51 name=?rva0032C2C4@TeamsInfoRec@@QAEXXZ evidence=?:placeholder tier=A
void TeamsInfoRec::removeOverriddenTeams()
{
	Int index = m_teams[0].m_next;
	while (index)
	{
		Int next = m_teams[index].m_next;
		if (m_teams[index].m_overriddenByID)
			removeTeam(index);
		index = next;
	}
}

