// FUNCTION: BFME2 0x0032D510 size=68 name=??4SidesInfo@@QAEAAV0@ABV0@@Z evidence=N:ledger tier=A
SidesInfo &SidesInfo::operator=(const SidesInfo &that)
{
	// copy, then trade contents with the copy, which takes the old ones away
	SidesInfo(that).swap(this);
	return *this;
}

